from pathlib import Path
import json, html, sys, shutil, re
from seo import prepare, finish, EXCLUDED, BASE
from local_content import MOVING, related, HOME_ANSWERS
PRODUCTION = "--production" in sys.argv
ROUTES = []

ROOT = Path(__file__).resolve().parents[1]/'outputs'/'nobleton-site'
if PRODUCTION:
    preview_root=ROOT
    ROOT=ROOT.parent/'nobleton-production'
    ROOT.mkdir(exist_ok=True)
    shutil.copytree(preview_root/'assets',ROOT/'assets',dirs_exist_ok=True)
    shutil.copy2(preview_root/'favicon.svg',ROOT/'favicon.svg')

def write(path, text):
    p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text)

resources = [
 {'slug':'nobleton-public-school','name':'Nobleton Public School','category':'Schools','description':'Public school information, school news and family resources from the York Region District School Board.','url':'https://nobleton-ps.yrdsb.ca/','detail':'Visit the school’s official website for current announcements and contact information. Confirm enrolment eligibility and attendance boundaries directly with the school board.'},
 {'slug':'st-mary-catholic-elementary-school','name':'St. Mary Catholic Elementary School','category':'Schools','description':'Catholic elementary education and school information for families in Nobleton.','url':'https://smy.ycdsb.ca/contact/','detail':'Located at 75 Greenside Drive, Nobleton. Contact the school or York Catholic District School Board for enrolment requirements and current attendance boundaries.'},
 {'slug':'nobleton-library','name':'Nobleton Library','category':'Community','description':'Your local branch for library services, reading and community discovery.','url':'https://www.kinglibrary.ca/hours-locations','detail':'The Nobleton branch is located at 8 Sheardown Drive. Check the library’s official website for current hours, holiday closures and available services.'},
 {'slug':'nobleton-community-park','name':'Nobleton Community Park','category':'Parks & recreation','description':'A local outdoor destination with play areas and sports amenities on Old King Road.','url':'https://www.king.ca/recreation-living/parks-trails-and-forestry/parks/nobleton-community-park','detail':'Located at 15 Old King Road. King Township lists playground and sports amenities at this park. Check the Township website for current access, seasonal availability and facility information.'},
 {'slug':'king-chamber','name':'King Chamber of Commerce','category':'Business resources','description':'Connections and resources for businesses across King Township, including Nobleton.','url':'https://www.kingchamber.ca/','detail':'The Chamber serves the broader King business community. Visit its website for membership information and current business events.'},
]
icons={'Schools':'▤','Community':'⌂','Parks & recreation':'♧','Business resources':'↗','Home services':'⌁','Food & drink':'◒','Health & wellness':'✳','Shopping':'◇'}
def card(r):
 return f'''<a class="listing" href="/directory/{r['slug']}/" data-category="{r['category']}" data-search="{html.escape((r['name']+' '+r['description']+' '+r['category']).lower())}"><span class="listing-icon" aria-hidden="true">{icons[r['category']]}</span><span class="eyebrow">{r['category']}</span><h3>{r['name']}</h3><p>{r['description']}</p><span class="card-foot">Public information <span aria-hidden="true">↗</span></span></a>'''
LOCAL_PHOTOS={
 'nobleton-hambly-house':('Hambly House, Nobleton · 2022','Peter Broster','https://commons.wikimedia.org/wiki/File:Hambly_House.jpg','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/',1536,864),
 'nobleton-lakes':('Nobleton Lakes · October 2006','Ken Mist','https://commons.wikimedia.org/wiki/File:Nobleton_Lakes_(274245513).jpg','CC BY 2.0','https://creativecommons.org/licenses/by/2.0/',1536,1152),
 'nobleton-roslyn-house':('Roslyn House, Nobleton · archive photo','Kingrd','https://commons.wikimedia.org/wiki/File:Nobleton_building.jpg','CC BY-SA 3.0','https://creativecommons.org/licenses/by-sa/3.0/',588,437)
}
def photo(name,alt,caption,extra='',eager=False):
 width,height=1536,1024
 if name in LOCAL_PHOTOS:
  title,author,source,license,license_url,width,height=LOCAL_PHOTOS[name]
  caption=f'{title} · <a href="/photo-credits/#{name}">Photo: {author} ↗</a>'
 small=min(width,768)
 sources=f'/assets/images/{name}-768.jpg {small}w, /assets/images/{name}.jpg {width}w' if width>768 else f'/assets/images/{name}.jpg {width}w'
 return f'<figure class="editorial-photo {extra}"><img src="/assets/images/{name}.jpg" srcset="{sources}" sizes="(max-width: 780px) 100vw, 50vw" alt="{alt}" width="{width}" height="{height}" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=high" if eager else ""}><figcaption>{caption}</figcaption></figure>'

def local_gallery():
 items=[('nobleton-hambly-house','Red-brick Hambly House with its central tower in Nobleton','A familiar landmark','Hambly House brings Nobleton’s architectural character into view.'),('nobleton-lakes','Pond and autumn foliage at Nobleton Lakes in 2006','A quieter side of Nobleton','An autumn view from Nobleton Lakes, photographed in October 2006.'),('nobleton-roslyn-house','Yellow wooden exterior and gabled roof of Roslyn House in Nobleton','Village character','An archival photograph of Roslyn House on Highway 27.')]
 return '<section class="wrap section local-gallery"><div class="section-heading"><div><p class="eyebrow">A SENSE OF PLACE</p><h2>Nobleton, through the lens.</h2></div><a class="text-link" href="/photo-credits/">Meet the photographers ↗</a></div><p class="gallery-intro">Local landmarks and landscapes from Nobleton in King Township. A small collection of real photographs, with their stories and sources.</p><div class="local-photo-grid">'+''.join('<article>'+photo(n,a,'',extra='gallery-photo')+f'<div class="gallery-copy"><h3>{t}</h3><p>{d}</p></div></article>' for n,a,t,d in items)+'</div></section>'

def enrich(body,path):
 street=('nobleton-hambly-house','Hambly House, a red-brick landmark with a central tower in Nobleton, photographed in 2022','')
 park=('nobleton-lakes','Pond framed by autumn foliage at Nobleton Lakes, photographed in October 2006','')
 home=('limestone-home','AI-generated luxury limestone country house with landscaped gardens','AI-generated home inspiration · Not a listing')
 terrace=('garden-residence','AI-generated luxury home with a timber-covered garden terrace','AI-generated home inspiration · Not a listing')
 if path=='/' and '<div class="hero-art">' in body:
  start=body.index('<div class="hero-art">'); end=body.index('</section>',start)
  body=body[:start]+'<div class="hero-art photo-hero">'+photo(*street,eager=True)+'<div class="art-caption"><span class="compass" aria-hidden="true">✳</span><span>Small-town roots.<br><strong>Room to discover.</strong></span></div></div>'+body[end:]
  body=body.replace('<div class="guide-links">',photo(*park,extra='guide-photo')+'<div class="guide-links">')
  body=body.replace('<article class="estate-feature">','<article class="estate-feature image-feature">'+photo(*home))
  body=body.replace('<article class="service-feature">','<article class="service-feature image-feature">'+photo(*street))
  body=body.replace('<div class="house-line" aria-hidden="true">⌂</div>','')
 elif path in ['/directory/','/guide/','/real-estate/','/find-a-service/','/submit/','/about/']:
  asset={'/directory/':street,'/guide/':park,'/real-estate/':home,'/find-a-service/':street,'/submit/':street,'/about/':street}[path]
  body=body.replace('<section class="page-intro">','<section class="page-intro visual-intro">',1)
  body=body.replace('</div></section>',photo(*asset,extra='intro-photo',eager=True)+'</div></section>',1)
  if path=='/real-estate/':
   body+='<section class="wrap section residence-story">'+photo(*terrace)+'<div><p class="eyebrow">ROOM TO MAKE IT YOURS</p><h2>A little more space.<br>A little closer to nature.</h2><p>Explore the community beyond the front door, from everyday essentials to places to unwind.</p><a class="text-link" href="/guide/">Discover life in Nobleton ↗</a></div></section>'
 elif path in ['/guide/parks/','/guide/essentials/']:
  body=body.replace('<article class="wrap reading section">','<article class="wrap reading section">'+photo(*(park if 'parks' in path else street),extra='article-photo'))
 if path in ['/', '/guide/']: body+=local_gallery()
 return body

def layout(title,desc,body,path='/',active=''):
 if path=='/': body+=HOME_ANSWERS+'''<section class="wrap join advertise-band"><div><p class="eyebrow">FOR LOCAL BUSINESSES</p><h2>Put your business in front of Nobleton.</h2><p>Interested in advertising on this site? Tell us about your business and what you want to promote.</p></div><a class="button" href="/advertise/">Advertise on Nobleton ↗</a></section>'''
 if path.startswith('/guide/') and path!='/guide/': body=body.replace('</article>',related()+'</article>')
 if path.startswith('/guide/') and path!='/guide/':
  headings=[]
  def anchor(m):
   label=m.group(1); ident='section-'+str(len(headings)+1); headings.append((ident,label)); return f'<h2 id="{ident}">{label}</h2>'
  body=re.sub(r'<h2>(.*?)</h2>',anchor,body)
  toc='<aside class="article-toc" aria-label="On this page"><h2>On this page</h2><ul>'+''.join(f'<li><a href="#{i}">{t}</a></li>' for i,t in headings)+'</ul></aside>'
  body=body.replace('<article class="wrap reading section">','<article class="wrap reading section">'+toc)
 body=enrich(body,path)
 title,desc,body,schema=prepare(title,desc,body,path,resources)
 ROUTES.append(path)
 form_script='<script src="https://unpkg.com/@formspree/ajax@1" defer></script>' if 'id="inquiry-form"' in body else ''
 robots='index,follow,max-image-preview:large' if PRODUCTION and path not in EXCLUDED else 'noindex,follow'
 preview_label='Independent local guide' if PRODUCTION else 'Community preview'
 nav=''.join(f'<a href="{u}"'+(' aria-current="page"' if active==k else '')+f'>{k}</a>' for k,u in [('Directory','/directory/'),('Local guide','/guide/'),('Real estate','/real-estate/'),('Find a service','/find-a-service/')])

 return f'''<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Nobleton</title><meta name="description" content="{html.escape(desc)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#1e493d"><link rel="canonical" href="{BASE}{path}"><meta property="og:title" content="{html.escape(title)} | Nobleton"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website"><meta property="og:site_name" content="Nobleton"><meta property="og:locale" content="en_CA"><meta property="og:image" content="{BASE}/assets/images/nobleton-hambly-house.jpg"><meta property="og:image:alt" content="Hambly House in Nobleton, photographed by Peter Broster in 2022; CC BY-SA 4.0"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{html.escape(title)} | Nobleton"><meta name="twitter:description" content="{html.escape(desc)}"><meta name="twitter:image" content="{BASE}/assets/images/nobleton-hambly-house.jpg"><meta property="og:url" content="{BASE}{path}"><link rel="icon" href="/favicon.svg?v=2" type="image/svg+xml" sizes="any"><link rel="stylesheet" href="/assets/style.css"><link rel="stylesheet" href="/assets/imagery.css"><script type="application/ld+json">{json.dumps(schema)}</script><script src="/assets/app.js" defer></script>{form_script}</head><body><a class="skip" href="#main">Skip to content</a><div class="topline"><span>NOBLETON, ONTARIO</span><span>A little closer to home.</span><span class="preview">{preview_label}</span></div><header><a class="brand" href="/" aria-label="Nobleton.ca home">Nobleton</a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation">{nav}<a class="button small" href="/submit/">Add your business <span aria-hidden="true">↗</span></a></nav></header><main id="main">{body}</main><footer><div class="footer-top"><div><a class="brand" href="/" aria-label="Nobleton.ca home">Nobleton</a><p>Your place to find your people.<br>An independent guide to Nobleton, Ontario.</p></div><div><h2>Explore</h2><a href="/directory/">Local directory</a><a href="/guide/">Living in Nobleton</a><a href="/real-estate/">Real estate</a></div><div><h2>Get involved</h2><a href="/submit/">Add or update a listing</a><a href="/advertise/">Advertise on Nobleton</a><a href="/find-a-service/">Request a service</a><a href="mailto:info@nobleton.ca">info@nobleton.ca</a></div><div><h2>About this guide</h2><a href="/about/">Our approach</a><a href="/standards/">Listing standards</a><a href="/privacy/">Privacy & contact</a><a href="/photo-credits/">Photo credits</a></div></div><div class="footer-bottom"><span>© 2026 Nobleton.ca</span><span>Independent community website. Not affiliated with the Township of King.</span></div></footer></body></html>'''
def page(slug,title,desc,body,active=''):
 write((slug+'/index.html').lstrip('/'),layout(title,desc,body,'/'+slug.strip('/')+'/',active))
