def form(kind):
 business=kind=='business'
 fields='''<label for="business">Business or organization name</label><input data-fs-field id="business" name="Business" required maxlength="120"><label for="website">Website (optional)</label><input data-fs-field id="website" name="Website" type="url" placeholder="https://" maxlength="250"><label for="service-area">Service area</label><input data-fs-field id="service-area" name="Service area" required placeholder="Nobleton, or areas you serve" maxlength="180">''' if business else '''<label for="area">Your area</label><input data-fs-field id="area" name="Area" required placeholder="Nobleton or nearby community" maxlength="120">'''
 return f'''<form class="email-form" id="inquiry-form" data-kind="{kind}" action="https://formspree.io/f/xljjnzbr" method="POST"><input type="hidden" name="_subject" value="Nobleton.ca {'business listing' if business else 'service request'}"><input type="hidden" name="inquiry_type" value="{kind}"><label for="name">Your name</label><input data-fs-field id="name" name="Name" autocomplete="name" required maxlength="100"><label for="email">Email address</label><input data-fs-field id="email" name="email" type="email" autocomplete="email" required maxlength="180">{fields}<label for="request-category">{'Listing category' if business else 'Service needed'}</label><select data-fs-field id="request-category" name="Category" required><option value="">Choose a category</option>{''.join(f'<option>{c}</option>' for c in list(icons)+['Other'])}</select><label for="details">{'About your business, or details to correct' if business else 'How can we help?'}</label><textarea data-fs-field id="details" name="message" rows="5" maxlength="1500" required placeholder="{'Tell us what you offer and where people can find you.' if business else 'Describe the service and approximate timing. Please leave out sensitive details.'}"></textarea><label class="check"><input data-fs-field type="checkbox" required name="Contact permission" value="Yes"><span>I agree that Nobleton.ca may contact me about this {'submission' if business else 'request'}. My details will not be shared with a provider without my permission.</span></label><p class="fine">Your details are sent securely through Formspree to the Nobleton.ca team when you select Send. <a href="/privacy/">Privacy information</a></p><button class="button" type="submit" data-fs-submit-btn>{'Send business submission' if business else 'Send service request'} ↗</button><p data-fs-success role="status" tabindex="-1" style="display:none">Thank you. Your {'business submission' if business else 'service request'} has been received. Our team will review your details.</p><p data-fs-error="email" role="alert"></p><p data-fs-error="message" role="alert"></p><p data-fs-error role="alert"></p><p class="fine">Having trouble? <a href="mailto:info@nobleton.ca">Email info@nobleton.ca</a>.</p></form>'''
page('submit','Add your business for free','Submit a free business listing or suggest a correction to the Nobleton directory.',intro('GROW WITH THE COMMUNITY','Let’s put your business on the local map.','Free submissions at launch. Tell us about your business or suggest an update to an existing entry.')+'<section class="wrap section form-layout"><aside><h2>A good introduction starts here.</h2><p>We welcome businesses based in Nobleton and providers that clearly serve the area.</p><ol><li>Tell us what you do.</li><li>We review your details.</li><li>We contact you if anything needs clarification.</li></ol><p>Submitting a listing does not guarantee publication. Please submit only details you’re authorized to share.</p><a class="text-link" href="/standards/">Read our listing standards ↗</a></aside>'+form('business')+'</section>')
page('find-a-service','Find a local service','Share a service request with Nobleton.ca as we build our local provider network.',intro('LOCAL HELP STARTS HERE','What can the neighbourhood help you with?','Tell us what you need. We’re building our provider network and will let you know whether a suitable connection is available.')+'<section class="wrap section form-layout"><aside><h2>One request.<br>A local starting point.</h2><p>Share the type of service, your area and approximate timing. The Nobleton.ca team reviews inquiries manually.</p><p>Our network is at an early stage. A match or response time is not guaranteed.</p><p>We’ll ask before passing your contact details to a provider. You choose whether to proceed and agree any pricing directly.</p><p class="fine">For emergencies, contact the appropriate emergency service directly.</p></aside>'+form('service')+'</section>','Find a service')

advertising_form=form('business').replace('data-kind="business"','data-kind="advertising"').replace('value="business"','value="advertising"').replace('Nobleton.ca business listing','Nobleton.ca advertising inquiry').replace('Listing category','Business category').replace('About your business, or details to correct','What would you like to promote?').replace('Tell us what you offer and where people can find you.','Tell us about your goals, preferred timing and budget, if known.').replace('Send business submission','Send advertising inquiry').replace('Your business submission has been received.','Your advertising inquiry has been received.').replace('this submission','this advertising inquiry')
page('advertise','Advertise on Nobleton: Local Business Inquiries','Interested in advertising to the Nobleton community? Contact our team about your business, campaign goals and potential opportunities.',intro('REACH THE LOCAL COMMUNITY','Your business. A local audience.','Explore advertising opportunities on Nobleton’s independent community guide.')+'<section class="wrap section form-layout"><aside><h2>Start a conversation.</h2><p>Tell us what you do, who you want to reach and what you want to promote. We’ll discuss possible placements, availability and pricing with you.</p><p>This is an inquiry, not a booking. No payment or commitment is required, and no audience size or results are guaranteed.</p><p>Any paid placements will be clearly labelled. Advertising inquiries are separate from our free directory submissions.</p><a class="text-link" href="/submit/">Looking for a free business listing? ↗</a></aside>'+advertising_form+'</section>')

page('about','About Nobleton.ca','An independent local guide connecting Nobleton residents, businesses and community information.',intro('SMALL-TOWN ROOTS','A more connected Nobleton.','A local starting point for the places, people and practical information around you.')+'''<article class="wrap reading section"><h2>Built for everyday local life</h2><p>Nobleton.ca brings together a community directory, sourced local guides, a developing service-referral network and an upcoming real-estate section.</p><h2>Free to get started</h2><p>Our launch is focused on building useful local coverage. Business submissions are free. If paid placements or referral arrangements are introduced later, they will be clearly disclosed.</p><h2>Independent and transparent</h2><p>We are not affiliated with the Township of King, local schools or organizations listed in public-resource entries. Their official websites remain the source for current service and enrolment information.</p><h2>Help shape the guide</h2><p>Recommend a resource, suggest a correction or ask a question at <a href="mailto:info@nobleton.ca">info@nobleton.ca</a>.</p></article>''')
page('standards','Listing standards','How Nobleton.ca reviews directory submissions and presents local information.',intro('CLEAR INFORMATION','A useful directory starts with trust.','Our approach to submissions, corrections and local coverage.')+'''<article class="wrap reading section"><h2>Local relevance</h2><p>Entries should be based in Nobleton or clearly serve its residents. Nearby providers must state their actual location and service area.</p><h2>Accurate details</h2><p>Submit your real business name, contact information, website and an accurate description. Claims about qualifications or credentials need supporting information. We do not publish invented ratings, testimonials or guarantees.</p><h2>Review and corrections</h2><p>We review submissions before publication and may ask for clarification. Public-resource entries cite official sources. To request a correction or removal, email info@nobleton.ca with the entry and relevant details.</p><h2>Clear relationships</h2><p>A listing is not an endorsement or a guarantee of service. Public-resource entries are distinguished from partnerships. Submissions are free at launch; future sponsored placements will be labelled.</p></article>''')
page('privacy','Privacy & contact','How Nobleton.ca handles form submissions and contact information.',intro('PRIVACY & CONTACT','You choose what to share.','Contact the Nobleton.ca team at info@nobleton.ca.')+'''<article class="wrap reading section"><h2>How website forms work</h2><p>When you submit a business listing, service request or advertising inquiry, the information you enter is sent to Formspree, our form-processing provider, for delivery to the Nobleton.ca team. This includes your name, email address, request details and any business or service-area information you provide. We use this information to review and respond to your inquiry.</p><p>Formspree processes submissions and technical information under its <a href="https://formspree.io/legal/privacy-policy/">privacy policy</a>. The form helper is loaded from the unpkg content delivery network. We do not store form contents in browser storage. Please do not include sensitive information.</p><h2>Email inquiries</h2><p>If you send an email, its contents and your email address are delivered through your email provider to info@nobleton.ca. We use inquiries to respond to the relevant request. We ask before sharing personal contact details with a service provider.</p><h2>Analytics and external links</h2><p>This preview does not load third-party analytics, advertising scripts or embedded real-estate feeds. External websites have their own privacy practices. The preview web server may record technical requests in its access log.</p><h2>Questions or corrections</h2><p>Email <a href="mailto:info@nobleton.ca">info@nobleton.ca</a> about your information or a directory correction.</p><p class="fine">Updated October 28, 2026 · Formspree handles website form submissions. Email info@nobleton.ca with questions about your submission or to request a correction or deletion.</p></article>''')
credits='<article class="wrap reading section"><p>These photographs show real places in Nobleton, King Township. Older photographs are presented as archival views; they do not confirm current conditions, public access or business operations. No endorsement by a photographer or property owner is implied.</p>'
for name,(title,author,source,license,license_url,width,height) in LOCAL_PHOTOS.items():
 credits+=f'<section id="{name}"><h2>{title}</h2>'+photo(name,title,'',extra='credit-photo')+f'<p>Photograph by {author}. <a href="{source}">Original photograph and source details on Wikimedia Commons</a>. Used under <a href="{license_url}">{license}</a>.</p><p>Changes: resized and compressed for the web; some placements crop the displayed image to fit. Adapted versions of share-alike images remain available under the same license.</p><p><a href="/assets/images/{name}.jpg">View the full website image</a></p></section>'
credits+='<h2>Illustrative property images</h2><p>Luxury home and garden images in the real-estate section are AI-generated inspiration, labelled as such. They are not photographs of Nobleton properties or active listings.</p></article>'
page('photo-credits','Nobleton Photography & Image Credits','Sources, photographers and licences for authentic Nobleton landmark and landscape photographs.',intro('BEHIND THE IMAGES','Real places. Credited photographers.','The people and sources behind our local image collection.')+credits)
write('404.html',layout('Page not found','Return to the Nobleton community guide.',intro('404','Let’s get you back to the neighbourhood.','This page could not be found.')+'<div class="wrap section"><a class="button" href="/">Back to home ↗</a></div>',path='/404.html'))
finish(ROOT,ROUTES,PRODUCTION)
